'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['summarizeDevice']);
const { summarizeDevice } = api;

const devices = [
  { name: 'Sensor', id: 1, categories: ['climate', 'outdoor'], metrics: { accuracy: 0.95, offset: -2, count: 0 } },
  { name: 'Relay', id: 2, categories: ['power'], metrics: {} },
  { name: 'UnknownCategory', id: 3, categories: ['other'], metrics: { value: 4 } }
];
const affinities = {
  climate: { helps: ['Garden', 'Garden'], hinders: ['Heater'] },
  outdoor: { helps: ['Ignored'], hinders: ['Also ignored'] },
  power: { helps: [], hinders: ['Battery'] }
};
const devicesBefore = JSON.parse(JSON.stringify(devices));
const affinitiesBefore = JSON.parse(JSON.stringify(affinities));
const result = summarizeDevice('Sensor', devices, affinities);
assert.deepStrictEqual(result, {
  name: 'Sensor',
  id: 1,
  categories: ['climate', 'outdoor'],
  metrics: { accuracy: 0.95, offset: -2, count: 0 },
  helpedBy: ['Garden', 'Garden'],
  hinderedBy: ['Heater']
});
assert.deepStrictEqual(devices, devicesBefore);
assert.deepStrictEqual(affinities, affinitiesBefore);
assert.deepStrictEqual(summarizeDevice('UnknownCategory', devices, affinities), {
  name: 'UnknownCategory', id: 3, categories: ['other'], metrics: { value: 4 }, helpedBy: [], hinderedBy: []
});
assert.deepStrictEqual(summarizeDevice('Missing', devices, affinities), { error: 'DEVICE_NOT_FOUND' });
assert.deepStrictEqual(summarizeDevice('Missing', [], {}), { error: 'DEVICE_NOT_FOUND' });

const second = summarizeDevice('Sensor', devices, affinities);
assert.notStrictEqual(result, second);
assert.notStrictEqual(result.categories, second.categories);
assert.notStrictEqual(result.metrics, second.metrics);
assert.notStrictEqual(result.helpedBy, second.helpedBy);
assert.notStrictEqual(result.hinderedBy, second.hinderedBy);
result.categories.push('changed');
result.metrics.accuracy = 0;
result.helpedBy[0] = 'changed';
result.hinderedBy.push('changed');
assert.deepStrictEqual(summarizeDevice('Sensor', devices, affinities), second);

assert.throws(() => summarizeDevice('Sensor', [devices[0], { name: 'Sensor', id: 9, categories: ['x'], metrics: {} }], {}), RangeError);
for (const badName of [undefined, null, '', 1]) assert.throws(() => summarizeDevice(badName, devices, affinities), TypeError);
for (const badDevices of [null, {}, 'x']) assert.throws(() => summarizeDevice('Sensor', badDevices, affinities), TypeError);
for (const bad of [
  null,
  [],
  { name: '', id: 1, categories: ['x'], metrics: {} },
  { name: 'X', id: 0, categories: ['x'], metrics: {} },
  { name: 'X', id: 1.5, categories: ['x'], metrics: {} },
  { name: 'X', id: 1, categories: [], metrics: {} },
  { name: 'X', id: 1, categories: [''], metrics: {} },
  { name: 'X', id: 1, categories: ['x'], metrics: [] },
  { name: 'X', id: 1, categories: ['x'], metrics: { bad: Infinity } },
  { name: 'X', id: 1, categories: ['x'], metrics: { bad: '1' } }
]) assert.throws(() => summarizeDevice('X', [bad], {}), TypeError);

for (const badAffinities of [null, [], 'x', { climate: null }, { climate: { helps: 'x', hinders: [] } }, { climate: { helps: [], hinders: [1] } }]) {
  assert.throws(() => summarizeDevice('Sensor', devices, badAffinities), TypeError);
}

